    // Find snippets mentioning prospective / student / phd / admit / recruit / join
    const matches = [];
    const sentences = text.split(/[.\n\r]+/);
    for (const s of sentences) {
      if (/prospective|accepting|recruit|phd student|apply|advis|join/i.test(s) && s.length < 300) {
        matches.push(s.trim());
      }
    }
    evidence.push({
