      school: t.school,
      url: t.url,
      labUrl: t.labUrl,
      area: t.area,
      snippets: matches.slice(0, 4)
    });
  } catch(e) {
    evidence.push({ prof: t.prof, error: e.message });
  }
}

await write("tmp://evidence_batch.json", JSON.stringify(evidence, null, 2), "application/json");
console.log("Evidence extracted for", evidence.length, "professors");

