];

for (const p of inspectList) {
  const res = await tool.fetch_url({ url: p.url });
  const clean = res.body.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ');
  console.log(`=== ${p.prof} (${p.school}) ===`);
  console.log("Full text length:", clean.length);
  // print first 500 chars and any prospective/apply/group/students mentions
  console.log("Head:", clean.slice(0, 400));
  // check links in html
  const links = [];
  const linkMatches = res.body.matchAll(/href=["']([^"']+)["'][^>]*>([^<]+)<\/a>/gi);
  for (const m of linkMatches) {
    if (/student|join|apply|group|lab|prospective|contact/i.test(m[1] + " " + m[2])) {
      links.push({ href: m[1], text: m[2].trim() });
    }
  }
  console.log("Relevant links:", links);
}

